const NEUTRAL_EVENT = Object.freeze({ id: "clear", name: "开阔轨道", routeDistanceMultiplier: 1, enemySpeedMultiplier: 1, eliteChanceMultiplier: 1, coreChanceMultiplier: 1, weather: "clear" });
